test("Telemetry SetterWrap", () => {
  const msg = new Telemetry();
  msg.device_id = -1294967296;
  assert.equal(msg.device_id, 3000000000, "device_id");
  msg.timestamp_us = -18446744061709551616n;
  assert.equal(msg.timestamp_us, 12000000000n, "timestamp_us");
  msg.timestamp_us = 7;
  assert.equal(msg.timestamp_us, 7n, "timestamp_us from a Number");
  msg.battery_mv = 125536;
  assert.equal(msg.battery_mv, 60000, "battery_mv");
});

test("Telemetry Strings", () => {
  const msg = new Telemetry();
  msg.callsign = "A";
  assert.equal(msg.callsign.length, 8);
  assert.equal(msg.callsign[0], 65);
  assert.equal(msg.callsignText, "A");
  msg.callsign = "x".repeat(8 + 3);
  assert.equal(msg.callsignText, "x".repeat(8));
  msg.callsign = [1, 2];
  const want = new Uint8Array(8);
  want.set([1, 2].slice(0, 8));
  assert.equal(hex(msg.callsign), hex(want));
  msg.callsign[0] = 9;
  assert.equal(msg.callsign[0], 1, "the getter returns a copy");
  assert.throws(() => { msg.callsign = 5; }, TypeError);
});
